bool LoadFile(const std::string& filename, std::string* result) {
  std::ifstream file(filename, std::ios::in | std::ios::binary);
  if (!file.is_open()) return false;
  std::ostringstream ss;
  ss << file.rdbuf();
  *result = ss.str();
  return true;
}

